package app.veyra;
import android.app.*;import android.os.Bundle;import android.content.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
public final class FollowsActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private LinearLayout root;private boolean busy;private String renderedProfile="";
 public void onCreate(Bundle saved){super.onCreate(saved);Ui.configure(this);render();}
 private void render(){renderedProfile=ProfileStore.id(this);root=Ui.column(this);Button back=Ui.quiet(this,"‹  Back");back.setOnClickListener(v->finish());root.addView(back);root.addView(Ui.text(this,"Keep up with your stories.",30,Ui.INK));root.addView(Ui.text(this,"Android checks followed series periodically when a connection is available. Larger libraries rotate through up to 20 titles per check; catalog listings determine availability.",14,Ui.MUTED));for(Map.Entry<String,JSONObject> entry:FollowStore.list(this).entrySet()){JSONObject title=entry.getValue();LinearLayout card=Ui.card(this);Button open=Ui.quiet(this,title.optString("vod_name"));open.setSingleLine(false);open.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class).putExtra("openTitle",title.toString())));card.addView(open);long checked=title.optLong("lastChecked");card.addView(Ui.text(this,title.optInt("episodeCount")+" episodes listed · "+(checked==0?"Not checked yet":java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT).format(new java.util.Date(checked))),13,Ui.MUTED));Button remove=Ui.quiet(this,"Unfollow");remove.setOnClickListener(v->{PersonalStore.prefs(this).edit().remove(entry.getKey()).apply();EpisodeMonitor.schedule(this);render();});card.addView(remove);root.addView(card);}if(FollowStore.list(this).isEmpty())root.addView(Ui.text(this,"Follow a series from its title page to see it here.",17,Ui.MUTED));Button refresh=Ui.primary(this,busy?"Checking…":"Check followed series");refresh.setEnabled(!busy);refresh.setOnClickListener(v->{busy=true;render();worker.execute(()->{try{int count=EpisodeMonitor.check(this,()->isDestroyed()||Thread.currentThread().isInterrupted());runOnUiThread(()->{if(isDestroyed())return;busy=false;render();Toast.makeText(this,"Checked "+count+" followed titles",Toast.LENGTH_LONG).show();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;busy=false;render();Toast.makeText(this,"Connect to the Internet and try again",Toast.LENGTH_LONG).show();});}});});root.addView(refresh);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);Ui.insets(this,scroll,20);}
 public void onResume(){super.onResume();if(!renderedProfile.equals(ProfileStore.id(this)))render();}
 public void onDestroy(){worker.shutdownNow();super.onDestroy();}
}
